        elif isinstance(row, str) and '|' in row:
            parts = row.split('|')
            try:
                weight = int(parts[1])
                status = parts[2]
                if status == 'OK':
                    weight = 1
                elif status == 'VOID':
                    pass
                else:
                    weight = 0
            except (ValueError, IndexError):
                weight = 0
        elif isinstance(row, list):
            total_int_sum = 0
            string_length_sum = 0
            for item in row:
                if isinstance(item, int) and not isinstance(item, bool):
                    total_int_sum += item
                elif isinstance(item, str):
                    string_length_sum += len(item)
            weight = total_int_sum + string_length_sum

        if (state + weight + original_index) % 11 not in (5, 0):
            kept_rows.append((row, weight, original_index))
        elif original_index == len(rows) - 1:
            kept_rows.append((row, weight, original_index))
        original_index += 1

        for kept_row, kept_weight, _ in kept_rows:
            if kept_weight == 0:
                state = 0
            else:
                state = (3 * state + kept_weight) % 11

    if not kept_rows:
        return []

    kept_length = len(kept_rows)
    final_state = state % kept_length
    rotated_rows = kept_rows[final_state:] + kept_rows[:final_state]

    result = []
    for key, value, _ in rotated_rows:
        if isinstance(key, str) and isinstance(value, int):
            result.append([key, value])

    result.sort()
    return result

